def transform(grid):
    from collections import Counter, deque
    H, W = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    rest = sorted([c for c in cnt if c != bg], key=lambda c: -cnt[c])
    marker = rest[0]
    special = rest[-1] if len(rest) > 1 else rest[0]
    out = [row[:] for row in grid]
    mcells = {(r, c) for r in range(H) for c in range(W) if grid[r][c] == marker}
    blocks = []
    seen = set()
    for cell in mcells:
        if cell in seen:
            continue
        comp = []
        dq = deque([cell])
        seen.add(cell)
        while dq:
            r, c = dq.popleft()
            comp.append((r, c))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                n = (r + dr, c + dc)
                if n in mcells and n not in seen:
                    seen.add(n)
                    dq.append(n)
        blocks.append(comp)
    if len(blocks) < 2:
        return out
    blocks.sort(key=lambda b: min((r, c) for r, c in b))

    def orient(b):
        rs = {r for r, _ in b}
        cs = {c for _, c in b}
        if len(rs) == 1:
            return 'h', rs.pop(), min(cs), max(cs)
        if len(cs) == 1:
            return 'v', cs.pop(), min(rs), max(rs)
        return None

    info = [orient(b) for b in blocks]
    scells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == special]
    for (r, c) in scells:
        adj = None
        for i, b in enumerate(blocks):
            if info[i] is None:
                continue
            o, pos, lo, hi = info[i]
            if o == 'h' and lo <= c <= hi:
                adj = i
            elif o == 'v' and lo <= r <= hi:
                adj = i
        if adj is None:
            adj = 0
        other = 1 - adj
        o, pos, lo, hi = info[adj]
        if o == 'h':
            step = -1 if pos < r else 1
            rr = r + step
            while 0 <= rr < H and grid[rr][c] not in (marker, special):
                out[rr][c] = special
                rr += step
            out[r][c] = 4
            o2, pos2, lo2, hi2 = info[other]
            if o2 == 'h':
                col = lo2 + (c - lo)
                for rr in range(H):
                    if grid[rr][col] != marker and grid[rr][col] != special:
                        out[rr][col] = special
        else:
            step = -1 if pos < c else 1
            cc = c + step
            while 0 <= cc < W and grid[r][cc] not in (marker, special):
                out[r][cc] = special
                cc += step
            out[r][c] = 4
            o2, pos2, lo2, hi2 = info[other]
            if o2 == 'v':
                row_ = lo2 + (r - lo)
                for cc in range(W):
                    if grid[row_][cc] != marker and grid[row_][cc] != special:
                        out[row_][cc] = special
    return out
